/* Current-DBA workflow using the existing ephemeris and boundary solver. */
(()=>{'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let results=[],version=0;
function current(){for(const [id,value]of [['tr-dba-selection-source','current'],['tr-date-range-source','period'],['tr-period','PD'],['tr-dasha-source','auto'],['tr-direction','all']])if($(id))$(id).value=value;KPTransitSelection.sync();KPTransit.refresh();const panel=$('tr-date-dba-selection');if(panel)panel.open=true;return KPTransit.currentPeriods();}
function sunTracks(data){const pairs=[['MD','AD','PD'],['MD','PD','AD'],['AD','MD','PD'],['AD','PD','MD'],['PD','MD','AD'],['PD','AD','MD']];return pairs.map(order=>{const lords=order.map(k=>data.periods[k].id),natal=$('tr-zone').value==='natal',points=lords.map(id=>currentKPModel.planets.find(p=>p.id===id));return {id:'sun:'+order.join('-'),planet:'Su',label:'Sun · '+order.map((k,i)=>k+' '+lords[i]+' '+['sign','star','sub'][i]).join(' + '),levels:['sign','star','sub'],test:p=>natal?p.signIndex===points[0].signIndex&&p.nakIndex===points[1].nakIndex&&p.nakIndex===points[2].nakIndex&&p.sl===points[2].sl:p.sgl===lords[0]&&p.stl===lords[1]&&p.sl===lords[2]};});}
function draw(){const tbody=$('tr-result-rows');tbody.replaceChildren();for(const row of results){const tr=document.createElement('tr');tr.dataset.track=row.trackId;tr.dataset.entry=row.start;tr.dataset.exit=row.end;for(const value of [row.planet,row.label,row.start,row.end]){const td=document.createElement('td');td.textContent=value;tr.append(td);}tbody.append(tr);}if(!results.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=4;td.textContent='No matching intervals in the selected MD / AD / PD window.';tr.append(td);tbody.append(tr);}}
async function run(){const token=++version;results=[];KPTransit.cancel();try{const data=KPTransit.selectedPeriods(),pd=data.periods.PD,range=KPTransit.currentRange(data),start=new Date(data.selection==='selected'||data.selection==='date'?range.start:Math.max(Date.now(),range.start.getTime())),end=new Date(range.end);if(end<=start)throw Error('The selected search period has ended. Choose another DBA or date range.');const mode=$('tr-mode').value,tracks=mode==='sun'?sunTracks(data):KPTransit.makeTracks(data);let periods=null;if(mode==='event'){const required=$('tr-houses').value.split(/[,\s]+/).filter(Boolean).map(Number);periods=KPEventOutcome.periodMatches(currentKPModel,{method:$('tr-significator-method').value},{start,end},required);if(!periods.length){draw();$('tr-status').textContent='Selected MD, AD and PD do not jointly support the selected event houses. No supported date found in this search range.';return;}}
$('tr-status').dataset.state='running';$('tr-run').disabled=true;$('tr-cancel').hidden=false;let found=await KPTransit.scan({start,end,tracks,shouldCancel:()=>token!==version,onProgress:p=>{if(token===version)$('tr-status').textContent='Searching selected MD / AD / PD… '+Math.round(p*100)+'%';}});if(token!==version)return;if(periods)found=KPEventOutcome.intersect(found,periods);results=found;draw();$('tr-status').dataset.state='complete';$('tr-status').textContent=results.length+' matching transit intervals · '+(data.selection==='selected'?'selected':'current')+' MD '+data.periods.MD.id+' / AD '+data.periods.AD.id+' / PD '+pd.id+' · selected period bounds. Entry is a transit boundary, not a guaranteed event date.';
}catch(e){if(token===version){$('tr-status').dataset.state='error';$('tr-status').textContent=e.message;}}finally{if(token===version){$('tr-run').disabled=false;$('tr-cancel').hidden=true;if($('tr-status').dataset.state==='running')$('tr-status').dataset.state='complete';}}}
function cancel(){version++;$('tr-status').dataset.state='idle';$('tr-status').textContent='Search cancelled.';$('tr-run').disabled=false;$('tr-cancel').hidden=true;}
function init(){document.querySelectorAll('#tr-planet-options input').forEach(n=>n.checked=true);const section=$('transit');section.classList.add('kp-current-dba-only');document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.id==='tr-run'){event.preventDefault();event.stopImmediatePropagation();run();}else if(button.id==='tr-cancel'){event.preventDefault();event.stopImmediatePropagation();cancel();}else if(button.dataset.trSearchMode){event.preventDefault();event.stopImmediatePropagation();KPHandyTransits.mode(button.dataset.trSearchMode);try{current();$('tr-date-dba-selection')?.scrollIntoView({block:'nearest'});}catch(e){$('tr-status').textContent=e.message;}}else if(button.id==='transit-preview'){event.preventDefault();event.stopImmediatePropagation();const table=section.querySelector('.tr-result-mount');KPChildGenderSheet.preview({title:'Transit dates · selected MD / AD / PD',html:'<article class="cg-page"><h2>Transit dates · selected MD / AD / PD</h2><p>'+esc($('tr-status').textContent)+'</p>'+(table?.outerHTML||'<p>No transit results are available.</p>')+'</article>',css:'table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #a8b8c5;padding:5px;overflow-wrap:anywhere;white-space:normal}thead{display:table-header-group}tr{break-inside:avoid}.tr-result-mount{overflow:visible!important;max-height:none!important}',lang:window.KPPreferences?.get().language||'english'});}else if(button.dataset.tab==='transit'||button.dataset.quickFunction==='transit'){setTimeout(()=>{try{current();}catch(e){$('tr-status').textContent=e.message;}},0);}},true);section.addEventListener('change',()=>{version++;results=[];},true);window.addEventListener('chart-manual-change',()=>{version++;results=[];});try{current();}catch(_){} }
window.KPTransitWorkspace=Object.freeze({run,cancel,getResults:()=>results.map(r=>({...r})),sunTracks,current});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,200));else init();})();
